1	//nolint:ireturn // bubbletea model methods in this file must return framework interfaces
2	package summarytui
3	
4	import (
5		"context"
6		"fmt"
7		"strconv"
8		"strings"
9	
10		"github.com/charmbracelet/bubbles/key"
11		"github.com/charmbracelet/bubbles/paginator"
12		"github.com/charmbracelet/bubbles/table"
13		tea "github.com/charmbracelet/bubbletea"
14		"github.com/entireio/cli/cmd/entire/cli/insightsdb"
15	)
16	
17	const defaultPageSize = 10
18	const rootVerticalChrome = 6
19	
20	// GenerateFunc generates summary and facets for a single session on demand.
21	// Returns the updated session row with populated summary/facet data.
22	type GenerateFunc func(ctx context.Context, row insightsdb.SessionRow) (insightsdb.SessionRow, error)
23	
24	type branchFilter int
25	
26	const (
27		filterRepo          branchFilter = iota // default branch (main/master)
28		filterCurrentBranch                     // current working branch
29		filterAllBranches                       // all branches
30	)
31	
32	//nolint:recvcheck // bubbletea pattern: value receiver for interface, pointer receivers for mutation helpers
33	type rootModel struct {
34		ctx           context.Context
35		rows          []insightsdb.SessionRow
36		filteredRows  []insightsdb.SessionRow
37		currentBranch string
38		defaultBranch string // repo's default branch (from origin/HEAD)
39		filter        branchFilter
40		table         table.Model
41		paginator     paginator.Model
42		pageSize      int
43		width         int
44		height        int
45		styles        styles
46		detailPage    *detailModel
47		generateFn    GenerateFunc
48		generating    bool
49	}
50	
51	type openDetailMsg struct {
52		row insightsdb.SessionRow
53	}
54	
55	type closeDetailMsg struct{}
56	
57	type generateDoneMsg struct {
58		row insightsdb.SessionRow
59	}
60	
61	type generateErrMsg struct {
62		err error
63	}
64	
65	func Run(ctx context.Context, rows []insightsdb.SessionRow) error {
66		return RunWithCurrentBranch(ctx, rows, "", "", nil)
67	}
68	
69	func RunWithCurrentBranch(_ context.Context, rows []insightsdb.SessionRow, currentBranch, defaultBranch string, generateFn GenerateFunc) error {
70		p := tea.NewProgram(newRootModel(rows, currentBranch, defaultBranch, generateFn), tea.WithAltScreen())
71		_, err := p.Run()
72		if err != nil {
73			return fmt.Errorf("run summary TUI: %w", err)
74		}
75		return nil
76	}
77	
78	func newRootModel(rows []insightsdb.SessionRow, currentBranch, defaultBranch string, generateFn GenerateFunc) rootModel {
79		columns := []table.Column{
80			{Title: "TIME", Width: 19},
81			{Title: "AGENT", Width: 16},
82			{Title: "BRANCH", Width: 26},
83			{Title: "CHECKPOINT", Width: 15},
84			{Title: "TOKENS", Width: 10},
85		}
86		styles := newStyles()
87		t := table.New(table.WithColumns(columns), table.WithFocused(true))
88		t.SetStyles(styles.tableStyles())
89		p := paginator.New()
90		p.PerPage = defaultPageSize
91		m := rootModel{
92			ctx:           context.Background(),
93			rows:          append([]insightsdb.SessionRow(nil), rows...),
94			currentBranch: currentBranch,
95			defaultBranch: defaultBranch,
96			filter:        filterRepo,
97			table:         t,
98			paginator:     p,
99			pageSize:      defaultPageSize,
100			styles:        styles,
101			width:         100,
102			height:        30,
103			generateFn:    generateFn,
104		}
105		m.rebuildFilteredRows()
106		return m
107	}
108	
109	func (m rootModel) Init() tea.Cmd {
110		return nil
111	}
112	
113	//nolint:cyclop,ireturn // required by bubbletea Model interface; state machine has inherent branching
114	func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
115		switch msg := msg.(type) {
116		case tea.WindowSizeMsg:
117			m.resize(msg.Width, msg.Height)
118			if m.detailPage != nil {
119				m.detailPage.setSize(m.width, m.height)
120			}
121			return m, nil
122	
123		case tea.KeyMsg:
124			if m.detailPage != nil {
125				return m.updateDetailKeys(msg)
126			}
127			return m.updateTableKeys(msg)
128	
129		case openDetailMsg:
130			m.detailPage = newDetailModel(m.styles, msg.row, m.generateFn != nil)
131			m.detailPage.setSize(m.width, m.height)
132			return m, nil
133	
134		case closeDetailMsg:
135			m.detailPage = nil
136			m.generating = false
137			return m, nil
138	
139		case generateDoneMsg:
140			m.generating = false
141			m.updateRowData(msg.row)
142			if m.detailPage != nil {
143				m.detailPage.row = msg.row
144				m.detailPage.status = "Generated"
145				m.detailPage.setSize(m.width, m.height) // re-render content
146			}
147			return m, nil
148	
149		case generateErrMsg:
150			m.generating = false
151			if m.detailPage != nil {
152				m.detailPage.status = "Error: " + msg.err.Error()
153			}
154			return m, nil
155		}
156	
157		var cmd tea.Cmd
158		m.table, cmd = m.table.Update(msg)
159		return m, cmd
160	}
161	
162	//nolint:ireturn // required by bubbletea pattern
163	func (m rootModel) updateDetailKeys(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
164		//nolint:exhaustive // only quit/back/generate keys handled; rest delegates to viewport
165		switch msg.Type {
166		case tea.KeyEsc:
167			return m, func() tea.Msg { return closeDetailMsg{} }
168		case tea.KeyCtrlC:
169			return m, tea.Quit
170		case tea.KeyRunes:
171			switch string(msg.Runes) {
172			case "q":
173				return m, tea.Quit
174			case "g":
175				if m.generateFn != nil && !m.generating && m.detailPage != nil {
176					m.generating = true
177					m.detailPage.status = "Generating summary and facets..."
178					row := m.detailPage.row
179					ctx := m.ctx
180					fn := m.generateFn
181					return m, func() tea.Msg {
182						updated, err := fn(ctx, row)
183						if err != nil {
184							return generateErrMsg{err: err}
185						}
186						return generateDoneMsg{row: updated}
187					}
188				}
189			}
190		default:
191		}
192		var cmd tea.Cmd
193		*m.detailPage, cmd = m.detailPage.update(msg)
194		return m, cmd
195	}
196	
197	//nolint:ireturn // required by bubbletea pattern
198	func (m rootModel) updateTableKeys(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
199		switch {
200		case key.Matches(msg, keys.cycleFilter):
201			m.cycleFilter()
202			return m, nil
203		case key.Matches(msg, keys.nextPage):
204			m.nextPage()
205			return m, nil
206		case key.Matches(msg, keys.prevPage):
207			m.prevPage()
208			return m, nil
209		case key.Matches(msg, keys.quit):
210			return m, tea.Quit
211		}
212	
213		//nolint:exhaustive // only command-specific keys are handled here; all others fall through to the table widget
214		switch msg.Type {
215		case tea.KeyEnter:
216			if row := m.selectedRow(); row != nil {
217				selected := *row
218				return m, func() tea.Msg { return openDetailMsg{row: selected} }
219			}
220		case tea.KeyCtrlC:
221			return m, tea.Quit
222		default:
223		}
224	
225		var cmd tea.Cmd
226		m.table, cmd = m.table.Update(msg)
227		return m, cmd
228	}
229	
230	func (m rootModel) View() string {
231		if m.detailPage != nil {
232			return m.detailPage.view()
233		}
234	
235		var b strings.Builder
236		b.WriteString(m.styles.render(m.styles.appTitle, "SESSION SUMMARY"))
237		b.WriteString("\n\n")
238		b.WriteString(renderFilterChips(m.styles, m.filter))
239		b.WriteString("  ")
240		b.WriteString(m.styles.render(m.styles.dim, pageLabel(m.paginator)))
241		b.WriteString("\n\n")
242		b.WriteString(m.table.View())
243		b.WriteString("\n\n")
244		b.WriteString(m.styles.render(m.styles.statusBar, "j/k navigate  f filter  ←/→ page  enter detail  q quit"))
245		return b.String()
246	}
247	
248	func (m *rootModel) updateRowData(updated insightsdb.SessionRow) {
249		for i, row := range m.rows {
250			if row.SessionID == updated.SessionID {
251				m.rows[i] = updated
252				break
253			}
254		}
255		for i, row := range m.filteredRows {
256			if row.SessionID == updated.SessionID {
257				m.filteredRows[i] = updated
258				break
259			}
260		}
261		m.rebuildTable()
262	}
263	
264	func (m *rootModel) rebuildFilteredRows() {
265		m.filteredRows = m.applyFilter()
266		m.paginator.PerPage = m.pageSize
267		totalPages := m.paginator.SetTotalPages(len(m.filteredRows))
268		if totalPages == 0 {
269			m.paginator.TotalPages = 1
270		}
271		if m.paginator.Page >= m.paginator.TotalPages {
272			m.paginator.Page = max(0, m.paginator.TotalPages-1)
273		}
274		if m.paginator.Page < 0 {
275			m.paginator.Page = 0
276		}
277		m.rebuildTable()
278	}
279	
280	func (m *rootModel) rebuildTable() {
281		pageRows := m.currentPageRows()
282		rows := make([]table.Row, 0, len(pageRows))
283		for _, row := range pageRows {
284			checkpoint := row.CheckpointID
285			if len(checkpoint) > 12 {
286				checkpoint = checkpoint[:12]
287			}
288			rows = append(rows, table.Row{
289				row.CreatedAt.Format("2006-01-02 15:04"),
290				row.Agent,
291				truncate(row.Branch, 24),
292				checkpoint,
293				strconv.Itoa(row.TotalTokens),
294			})
295		}
296		m.table.SetRows(rows)
297		if len(rows) == 0 {
298			m.table.SetCursor(0)
299			return
300		}
301		if m.table.Cursor() >= len(rows) {
302			m.table.SetCursor(len(rows) - 1)
303		}
304	}
305	
306	func (m rootModel) selectedRow() *insightsdb.SessionRow {
307		rows := m.currentPageRows()
308		idx := m.table.Cursor()
309		if idx < 0 || idx >= len(rows) {
310			return nil
311		}
312		return &rows[idx]
313	}
314	
315	func (m rootModel) applyFilter() []insightsdb.SessionRow {
316		filtered := make([]insightsdb.SessionRow, 0, len(m.rows))
317		for _, row := range m.rows {
318			if m.filter == filterRepo && m.defaultBranch != "" && row.Branch != m.defaultBranch {
319				continue
320			}
321			if m.filter == filterCurrentBranch && m.currentBranch != "" && row.Branch != m.currentBranch {
322				continue
323			}
324			filtered = append(filtered, row)
325		}
326		return filtered
327	}
328	
329	func (m rootModel) currentPageRows() []insightsdb.SessionRow {
330		if len(m.filteredRows) == 0 {
331			return nil
332		}
333		start, end := m.paginator.GetSliceBounds(len(m.filteredRows))
334		if start >= len(m.filteredRows) {
335			return nil
336		}
337		if end > len(m.filteredRows) {
338			end = len(m.filteredRows)
339		}
340		return m.filteredRows[start:end]
341	}
342	
343	func (m *rootModel) cycleFilter() {
344		m.filter = (m.filter + 1) % 3
345		m.paginator.Page = 0
346		m.table.SetCursor(0)
347		m.rebuildFilteredRows()
348	}
349	
350	func (m *rootModel) nextPage() {
351		if m.paginator.OnLastPage() {
352			return
353		}
354		m.paginator.NextPage()
355		m.table.SetCursor(0)
356		m.rebuildTable()
357	}
358	
359	func (m *rootModel) prevPage() {
360		if m.paginator.OnFirstPage() {
361			return
362		}
363		m.paginator.PrevPage()
364		m.table.SetCursor(0)
365		m.rebuildTable()
366	}
367	
368	func pageLabel(p paginator.Model) string {
369		return fmt.Sprintf("Page %d/%d", p.Page+1, max(1, p.TotalPages))
370	}
371	
372	func renderFilterChips(styles styles, active branchFilter) string {
373		labels := []struct {
374			filter branchFilter
375			label  string
376		}{
377			{filterRepo, "Repo"},
378			{filterCurrentBranch, "Current Branch"},
379			{filterAllBranches, "All"},
380		}
381	
382		parts := make([]string, 0, len(labels))
383		for _, item := range labels {
384			text := item.label
385			if item.filter == active {
386				text = "[" + text + "]"
387				parts = append(parts, styles.render(styles.chipActive, text))
388				continue
389			}
390			parts = append(parts, styles.render(styles.chipInactive, text))
391		}
392		return strings.Join(parts, " ")
393	}
394	
395	func (m *rootModel) resize(width, height int) {
396		selectedSessionID := ""
397		if selected := m.selectedRow(); selected != nil {
398			selectedSessionID = selected.SessionID
399		}
400	
401		m.width = width
402		m.height = height
403		m.table.SetWidth(width)
404	
405		tableHeight := max(3, height-rootVerticalChrome)
406		m.table.SetHeight(tableHeight)
407		m.pageSize = max(1, tableHeight-1)
408	
409		m.rebuildFilteredRows()
410		m.restoreSelection(selectedSessionID)
411	}
412	
413	func (m *rootModel) restoreSelection(sessionID string) {
414		if sessionID == "" || len(m.filteredRows) == 0 {
415			return
416		}
417	
418		for idx, row := range m.filteredRows {
419			if row.SessionID != sessionID {
420				continue
421			}
422	
423			m.paginator.Page = idx / m.pageSize
424			m.rebuildTable()
425	
426			cursor := idx % m.pageSize
427			if pageRows := m.currentPageRows(); len(pageRows) > 0 && cursor >= len(pageRows) {
428				cursor = len(pageRows) - 1
429			}
430			m.table.SetCursor(cursor)
431			return
432		}
433	}
