26	type summaryOptions struct {
27		Last       int
28		Agent      string
29		Branch     string
30		Me         bool
31		OutputJSON bool
32	}
33	
34	const (
35		defaultSummarySessionLimit = 10
36		maxSummaryRecentSessions   = 200
37	)
