67	func newSummaryCmd() *cobra.Command {
68		opts := summaryOptions{Last: defaultSummarySessionLimit}
69	
70		cmd := &cobra.Command{
71			Use:   "summary",
72			Short: "Browse source sessions with summaries and facets",
73			RunE: func(cmd *cobra.Command, _ []string) error {
74				ctx := cmd.Context()
75				w := cmd.OutOrStdout()
76	
77				if checkDisabledGuard(ctx, w) {
78					return nil
79				}
80	
81				if !settings.IsSummarizeEnabled(ctx) {
82					fmt.Fprintln(w, "Summarization is required for summary browsing. Enable it in .entire/settings.json:")
83					fmt.Fprintln(w, `  { "strategy_options": { "summarize": { "enabled": true } } }`)
84					return nil
85				}
86	
87				return runSummary(ctx, w, opts)
