99	func runSummary(ctx context.Context, w io.Writer, opts summaryOptions) error {
100		rows, err := loadSummarySessions(ctx, opts)
101		if err != nil {
102			return err
103		}
104	
105		if opts.OutputJSON {
106			return renderSummaryJSON(w, rows)
107		}
108	
109		if IsAccessibleMode() {
110			renderSummaryText(w, rows)
111			return nil
112		}
113	
114		currentBranch := ""
115		if branch, err := GetCurrentBranch(ctx); err == nil {
116			currentBranch = branch
117		}
118		defaultBranch := GetDefaultBranch(ctx)
119	
120		return runSummaryTUI(ctx, rows, currentBranch, defaultBranch, generateForSession)
121	}
122	
123	func loadSummarySessions(ctx context.Context, opts summaryOptions) ([]insightsdb.SessionRow, error) {
124		worktreeRoot, err := paths.WorktreeRoot(ctx)
125		if err != nil {
126			return nil, fmt.Errorf("not in a git repository: %w", err)
127		}
128	
129		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
130		if err != nil {
131			return nil, fmt.Errorf("open insights cache: %w", err)
132		}
133		defer func() { _ = idb.Close() }()
134	
135		outputLimit := normalizedSummarySessionLimit(opts.Last)
136	
137		rows, err := idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
138		if err != nil {
139			return nil, fmt.Errorf("query sessions: %w", err)
140		}
141		if len(rows) == 0 {
142			// First-run fallback: populate the cache if we have nothing local yet.
143			if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
144				return nil, fmt.Errorf("refresh insights cache: %w", err)
145			}
146			rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
147			if err != nil {
148				return nil, fmt.Errorf("query sessions after refresh: %w", err)
149			}
150		}
151	
152		summaryBackfillSummaries(ctx, io.Discard, idb, outputLimit)
153		summaryBackfillFacets(ctx, io.Discard, idb, outputLimit)
154	
155		rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
156		if err != nil {
157			return nil, fmt.Errorf("query sessions after backfill: %w", err)
158		}
159	
160		ownerID := ""
161		if opts.Me {
162			ownerID, err = githubidentity.ResolveUsername(ctx)
163			if err != nil {
164				return nil, fmt.Errorf("resolve github username: %w", err)
165			}
166		}
167	
168		hasCLIFilters := opts.Agent != "" || opts.Branch != "" || ownerID != ""
169	
170		filtered := make([]insightsdb.SessionRow, 0, len(rows))
171		for _, row := range rows {
172			if opts.Agent != "" && !strings.EqualFold(strings.TrimSpace(row.Agent), strings.TrimSpace(opts.Agent)) {
173				continue
174			}
175			if opts.Branch != "" && !strings.EqualFold(strings.TrimSpace(row.Branch), strings.TrimSpace(opts.Branch)) {
176				continue
177			}
178			if ownerID != "" && !strings.EqualFold(strings.TrimSpace(row.OwnerID), ownerID) {
179				continue
180			}
181			filtered = append(filtered, row)
182			// Only cap results when CLI filters or JSON output are in use.
183			// The TUI has its own branch filter, so it needs the full result set.
184			if hasCLIFilters && len(filtered) == outputLimit {
185				break
186			}
187		}
188	
189		return filtered, nil
190	}
191	
192	func normalizedSummarySessionLimit(last int) int {
193		if last <= 0 {
194			return defaultSummarySessionLimit
195		}
196		return min(last, maxSummaryRecentSessions)
197	}
