228				}
229				if row.OwnerEmail != "" {
230					fmt.Fprintf(w, "Author Email: %s\n", row.OwnerEmail)
231				}
232			}
233			if row.Branch != "" {
234				fmt.Fprintf(w, "Branch: %s\n", row.Branch)
235			}
236			fmt.Fprintf(w, "Checkpoint: %s\n", row.CheckpointID)
237			fmt.Fprintf(w, "Summary: %s  Facets: %s\n", yesNo(row.HasSummary), yesNo(row.HasFacets))
238	
239			if row.HasSummary {
240				fmt.Fprintln(w, "Intent:")
241				fmt.Fprintf(w, "  %s\n", fallbackText(row.Intent, "No summary cached"))
242				fmt.Fprintln(w, "Outcome:")
243				fmt.Fprintf(w, "  %s\n", fallbackText(row.Outcome, "No summary cached"))
244				renderStringListSection(w, "Friction", row.Friction, "No friction recorded")
245				renderLearningSection(w, row.Learnings)
246			} else {
247				fmt.Fprintln(w, "No summary cached")
