301			}
302		}
303	
304		fmt.Fprintln(w, "Failure Loops:")
305		if len(data.FailureLoops) == 0 {
306			fmt.Fprintln(w, "  None")
307		} else {
308			for _, item := range data.FailureLoops {
309				fmt.Fprintf(w, "  - %s (%d)\n", item.Description, item.Count)
310			}
311		}
312	
313		fmt.Fprintln(w, "Skill Signals:")
314		if len(data.SkillSignals) == 0 {
315			fmt.Fprintln(w, "  None")
316		} else {
317			for _, item := range data.SkillSignals {
318				fmt.Fprintf(w, "  - %s\n", item.SkillName)
319			}
320		}
321	
322		fmt.Fprintln(w, "Repo Gotchas:")
323		if len(data.RepoGotchas) == 0 {
324			fmt.Fprintln(w, "  None")
325		} else {
326			for _, item := range data.RepoGotchas {
327				fmt.Fprintf(w, "  - %s\n", item)
328			}
329		}
330	
331		fmt.Fprintln(w, "Workflow Gaps:")
332		if len(data.WorkflowGaps) == 0 {
333			fmt.Fprintln(w, "  None")
334		} else {
335			for _, item := range data.WorkflowGaps {
336				fmt.Fprintf(w, "  - %s\n", item)
337			}
338		}
339	}
340	
341	func renderStringListSection(w io.Writer, title string, items []string, empty string) {
342		fmt.Fprintf(w, "%s:\n", title)
343		if len(items) == 0 {
344			fmt.Fprintf(w, "  %s\n", empty)
345			return
346		}
347		for _, item := range items {
348			fmt.Fprintf(w, "  - %s\n", item)
349		}
350	}
351	
352	func summarySessionToView(row insightsdb.SessionRow) summarySessionView {
353		return summarySessionView{
354			CheckpointID: row.CheckpointID,
355			SessionID:    row.SessionID,
356			Agent:        row.Agent,
357			Model:        row.Model,
358			Branch:       row.Branch,
359			OwnerID:      row.OwnerID,
360			CreatedAt:    row.CreatedAt.Format("2006-01-02T15:04:05Z07:00"),
361			Tokens:       row.TotalTokens,
362			Turns:        row.TurnCount,
363			HasSummary:   row.HasSummary,
364			HasFacets:    row.HasFacets,
365			Summary: summaryDetailView{
366				Intent:    row.Intent,
367				Outcome:   row.Outcome,
368				Friction:  row.Friction,
369				Learnings: row.Learnings,
370			},
371			Facets: row.Facets,
372		}
373	}
374	
375	func yesNo(v bool) string {
376		if v {
377			return "yes"
378		}
379		return "no"
380	}
381	
382	func fallbackText(value, fb string) string {
383		if strings.TrimSpace(value) == "" {
384			return fb
385		}
386		return value
387	}
388	
389	// generateForSession generates summary and facets for a single session on demand.
390	// It opens its own database connection and checkpoint store.
391	func generateForSession(ctx context.Context, row insightsdb.SessionRow) (insightsdb.SessionRow, error) {
392		repo, err := openRepository(ctx)
393		if err != nil {
394			return row, fmt.Errorf("open repository: %w", err)
395		}
396		store := checkpoint.NewGitStore(repo)
397	
398		cpID, err := checkpointid.NewCheckpointID(row.CheckpointID)
399		if err != nil {
400			return row, fmt.Errorf("invalid checkpoint ID: %w", err)
401		}
402	
403		content, err := store.ReadSessionContent(ctx, cpID, row.SessionIndex)
404		if err != nil {
405			return row, fmt.Errorf("read session content: %w", err)
406		}
407		if len(content.Transcript) == 0 {
408			return row, fmt.Errorf("empty transcript for checkpoint %s", row.CheckpointID)
409		}
410	
411		condensed, err := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
412		if err != nil {
413			return row, fmt.Errorf("condense transcript: %w", err)
414		}
415		if len(condensed) == 0 {
416			return row, fmt.Errorf("condensed transcript empty for checkpoint %s", row.CheckpointID)
417		}
418	
419		input := summarize.Input{
420			Transcript:   condensed,
421			FilesTouched: row.FilesTouched,
422		}
423	
424		// Generate summary.
425		gen := &summarize.ClaudeGenerator{}
426		summary, genErr := gen.Generate(ctx, input)
427		if genErr != nil {
428			logging.Debug(ctx, "generateForSession: summary generation failed",
429				"checkpoint_id", row.CheckpointID, "error", genErr)
430		}
431		if summary != nil {
432			content.Metadata.Summary = summary
433			row = metadataToSessionRow(row.CheckpointID, row.SessionIndex, &content.Metadata)
434		}
435	
436		// Extract facets.
437		formatted := summarize.FormatCondensedTranscript(input)
438		extractor := &facets.Extractor{Runner: &llmcli.Runner{}}
439		facetResult, _, extractErr := extractor.Extract(ctx, formatted)
440		if extractErr != nil {
441			logging.Debug(ctx, "generateForSession: facet extraction failed",
442				"checkpoint_id", row.CheckpointID, "error", extractErr)
443		}
444		if facetResult != nil {
445			row.Facets = *facetResult
446			row.HasFacets = true
447		}
448	
449		// Persist to database.
450		worktreeRoot, err := paths.WorktreeRoot(ctx)
451		if err != nil {
452			return row, fmt.Errorf("find worktree root: %w", err)
453		}
454		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
455		if err != nil {
456			return row, fmt.Errorf("open insights db: %w", err)
457		}
458		defer func() { _ = idb.Close() }()
459	
460		if row.HasSummary {
461			if updateErr := idb.UpdateSessionSummary(ctx, row); updateErr != nil {
462				return row, fmt.Errorf("save summary: %w", updateErr)
463			}
464		}
465		if row.HasFacets {
466			if updateErr := idb.UpdateSessionFacets(ctx, row); updateErr != nil {
467				return row, fmt.Errorf("save facets: %w", updateErr)
468			}
469		}
470	
471		// Return partial success even if one phase failed.
472		if genErr != nil && extractErr != nil {
473			return row, fmt.Errorf("summary: %w; facets: %w", genErr, extractErr)
474		}
475		return row, nil
476	}
477

